    }
}

public class Main {
    static int sum(int[]... groups) {
        int total = 0;
        for (int[] group : groups) {
            for (int value : group) {
                total += value;
            }
        }
        return total;
    }
    public static void main(String[] args) {
        int[] a = {1, 2};
        int[] b = {3};
        System.out.print(sum(a, b) + ":");
        System.out.print(sum(new int[] {4, 5}));
    }
}

